💡 **SUGGESTION: `findActiveTargetRun` is exported as a "pure decision/filter helper" but has a `console.log` side effect**

`autoStart.js:49` logs the duplicate-run notice from inside `findActiveTargetRun`, so the helper the PR description (and the `module.exports` comment: "extracted pure decision/filter helpers") calls pure actually performs I/O. It also makes the helper awkward to reuse silently.

Consider moving the log up into `hasActiveTargetRun` (the only caller):

```js
// findActiveTargetRun: match only, no logging
function findActiveTargetRun(runs, configFile, ticketKey, status) {
    for (var j = 0; j < runs.length; j++) {
        var run = runs[j] || {};
        if (isStaleNonRunningWorkflowRun(run, status)) continue;
        if (workflowRunMatchesTicket(workflowRunDisplayName(run), configFile, ticketKey)) {
            return run;
        }
    }
    return null;
}

// hasActiveTargetRun
var match = findActiveTargetRun(parseWorkflowRuns(runsRaw), configFile, ticketKey, statuses[i]);
if (match) {
    console.log(duplicateRunNotice(configFile + ' : ' + ticketKey, match, statuses[i]));
    return true;
}
```

